components/gordonbyte/common/brands/bran:
{{#if theme_settings.gb-brands-imagesOne }}
<div class="brands-section bg-img product-sections">

    {{#if theme_settings.gb-brands-title }}
      <h2 class="page-heading"><span>{{ theme_settings.gb-brands-title }}</span></h2>
    {{/if}}

    {{{region name="home_brands_description"}}}

    <div class="brands-selections brands-row1">
      <div class="brands-selections-holder" data-slick='{
        "mobileFirst": true,
        "autoplay": true,
        "slidesToShow": 2,
        "slidesToScroll": 2,
        "responsive": [
        {
          "breakpoint": 1201,
          "settings": {
            "slidesToShow": 6,
            "slidesToScroll": 1,
            "infinite": true,
            "dots": false
          }
        },
        {
          "breakpoint": 992,
          "settings": {
            "slidesToShow": 4,
            "slidesToScroll": 1,
            "infinite": true,
            "dots": false
          }
        },
        {
          "breakpoint": 768,
          "settings": {
            "slidesToShow": 3,
            "slidesToScroll": 3,
            "infinite": true,
            "dots": false
          }
        },
        {
          "breakpoint": 550,
          "settings": {
            "slidesToShow": 2,
            "slidesToScroll": 2,
            "infinite": true,
            "dots": false
          }
        }
        ],
        "dots": false,
        "lazyLoad": "anticipated",
        "slide": ".brands-slide",
        "prevArrow": ".brands-prev-arrow",
        "nextArrow": ".brands-next-arrow"
    }'>
		<button aria-label="{{lang 'carousel.arrowAriaLabel'}} {{carousel.slides.length}}" class="brands-prev-arrow slick-prev slick-arrow">hero-prev-arrow</button>


    {{#each (split theme_settings.gb-brands-imagesOne  "|") }}
            <div class="brands-slide">
              <a>
                <div class="brand-icon">
                  <img src="{{getImageManagerImage this }}"
                        data-sizes="auto"
                        alt="{{this}}"
                        {{#unless lazyload '==' 'disabled'}}
                            {{#if lazyload '==' 'lazyload+lqip'}}
                            {{!-- If we want a LQIP, include it as the default srcset (will be overwritten by lazysizes) --}}
                            srcset="{{getImageManagerImageSrcset this }}"
                            {{else}}
                              {{!-- If we don't want a LQIP, use a 1px transparent gif for the stand-in image
                                    This requires no additional network request, so it's fast --}}
                            srcset="data:image/gif;base64,R0lGODlhAQABAIAAAP///wAAACH5BAEAAAAALAAAAAABAAEAAAICRAEAOw=="
                            {{/if}}
                        {{/unless}}

                        {{#unless lazyload '==' 'disabled'}}data-{{/unless}}srcset="{{getImageManagerImageSrcset this use_default_sizes=true }}"

                        class="{{#unless lazyload '==' 'disabled'}}lazyload{{/unless}}"
                        {{#if lazyload '==' 'lazyload'}}loading="lazy"{{/if}}
                        >
                </div>
              </a>
            </div>
		{{/each}}

		{{#each (split theme_settings.gb-brands-imagesTwo  "|") }}
            <div class="brands-slide">
              <a>
                <div class="brand-icon">
                  <img src="{{getImageManagerImage this }}"
                        data-sizes="auto"
                        alt="{{this}}"
                        {{#unless lazyload '==' 'disabled'}}
                            {{#if lazyload '==' 'lazyload+lqip'}}
                            {{!-- If we want a LQIP, include it as the default srcset (will be overwritten by lazysizes) --}}
                            srcset="{{getImageManagerImageSrcset this }}"
                            {{else}}
                              {{!-- If we don't want a LQIP, use a 1px transparent gif for the stand-in image
                                    This requires no additional network request, so it's fast --}}
                            srcset="data:image/gif;base64,R0lGODlhAQABAIAAAP///wAAACH5BAEAAAAALAAAAAABAAEAAAICRAEAOw=="
                            {{/if}}
                        {{/unless}}

                        {{#unless lazyload '==' 'disabled'}}data-{{/unless}}srcset="{{getImageManagerImageSrcset this use_default_sizes=true }}"

                        class="{{#unless lazyload '==' 'disabled'}}lazyload{{/unless}}"
                        {{#if lazyload '==' 'lazyload'}}loading="lazy"{{/if}}
                        >
                </div>
              </a>
            </div>
		{{/each}}

		{{#each (split theme_settings.gb-brands-imagesThree  "|") }}
            <div class="brands-slide">
              <a>
                <div class="brand-icon">
                  <img src="{{getImageManagerImage this }}"
                        data-sizes="auto"
                        alt="{{this}}"
                        {{#unless lazyload '==' 'disabled'}}
                            {{#if lazyload '==' 'lazyload+lqip'}}
                            {{!-- If we want a LQIP, include it as the default srcset (will be overwritten by lazysizes) --}}
                            srcset="{{getImageManagerImageSrcset this }}"
                            {{else}}
                              {{!-- If we don't want a LQIP, use a 1px transparent gif for the stand-in image
                                    This requires no additional network request, so it's fast --}}
                            srcset="data:image/gif;base64,R0lGODlhAQABAIAAAP///wAAACH5BAEAAAAALAAAAAABAAEAAAICRAEAOw=="
                            {{/if}}
                        {{/unless}}

                        {{#unless lazyload '==' 'disabled'}}data-{{/unless}}srcset="{{getImageManagerImageSrcset this use_default_sizes=true }}"

                        class="{{#unless lazyload '==' 'disabled'}}lazyload{{/unless}}"
                        {{#if lazyload '==' 'lazyload'}}loading="lazy"{{/if}}
                        >
                </div>
              </a>
            </div>
		{{/each}}

		<button aria-label="{{lang 'carousel.arrowAriaLabel'}} {{carousel.slides.length}}" class="brands-next-arrow slick-next slick-arrow">hero-next-arrow</button>

      </div>
    </div><!--.category-selections ends-->

</div>

{{else}}

  {{#if theme_settings.gb-theme-demo }}
